import pytest


def age_at(born: int, now: int) -> int:
    """Return the whole number of years from birth year `born` to current year `now`.

    The current year is passed in explicitly; this function must not read the system clock.
    """
    return now - born


def test_age_in_birth_year_is_zero() -> None:
    assert age_at(2024, 2024) == 0


def test_age_counts_whole_years() -> None:
    assert age_at(1990, 2024) == 34


def test_age_one_year_later() -> None:
    assert age_at(2000, 2001) == 1


def test_age_is_deterministic_for_same_inputs() -> None:
    assert age_at(1985, 2020) == age_at(1985, 2020)
